class Solution {
    public int maximumSaleItems(int[][] items, int budget) {
        int n = items.length;

        // Step 1: Calculate free items generated by each item
        int[] weight = new int[n];

        for (int i = 0; i < n; i++) {
            weight[i] = 1;

            for (int j = 0; j < n; j++) {
                if (i != j && items[j][0] % items[i][0] == 0) {
                    weight[i]++;
                }
            }
        }

        // Step 2: Group items by price
        List<Integer>[] groups = new ArrayList[budget + 1];

        for (int i = 0; i <= budget; i++) {
            groups[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            int price = items[i][1];

            if (price <= budget) {
                groups[price].add(weight[i]);
            }
        }

        // Step 3: Knapsack DP
        int NEG = -1000000000;

        int[] dp = new int[budget + 1];
        Arrays.fill(dp, NEG);
        dp[0] = 0;

        int ans = 0;

        // Process prices from highest to lowest
        for (int p = budget; p >= 1; p--) {

            if (groups[p].isEmpty()) {
                continue;
            }

            // Sort rewards in descending order
            Collections.sort(groups[p], Collections.reverseOrder());

            int[] next = dp.clone();

            int prefix = 0;
            int limit = Math.min(groups[p].size(), budget / p);

            for (int k = 1; k <= limit; k++) {
                prefix += groups[p].get(k - 1);

                int cost = k * p;

                for (int c = cost; c <= budget; c++) {

                    if (dp[c - cost] == NEG) {
                        continue;
                    }

                    int value = dp[c - cost] + prefix;

                    next[c] = Math.max(next[c], value);

                    // Extra copies of the cheapest selected item
                    int extra = (budget - c) / p;

                    ans = Math.max(ans, value + extra);
                }
            }

            dp = next;
        }

        return ans;
    }
}